 const hold=(el,down,up)=>{if(!el)return;el.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();down();});for(const ev of ['pointerup','pointerleave','pointercancel'])el.addEventListener(ev,up);el.addEventListener('keydown',e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();if(!e.repeat)down();}});el.addEventListener('keyup',e=>{if(e.key===' '||e.key==='Enter')up();});};
