const rgbCss=c=>`rgb(${c.join(',')})`;
function mixerPanel(free){const done=!free&&mx.round>=RGB_TARGETS.length,target=RGB_TARGETS[mx.round],lvl=Math.max(...mx.rgb)/255;return `<div class="rgb-stage"><div>${glowLed('rl',rgbCss(mx.rgb),lvl)}</div>${!free&&!done?`<div class="swatch-box"><div class="swatch" style="background:${rgbCss(target.rgb)}"></div><span>${t('Target {i} / {n}: {name}',{i:mx.round+1,n:RGB_TARGETS.length,name:t(target.name)})}</span></div>`:''}</div><div class="lab-lower"><div><div class="code-label">SKETCH.INO · RGB</div><pre><code id="rgb-sketch">${esc(sk(makeRgbSketch(mx.rgb)))}</code></pre></div><div><div class="lab-control">${['Red','Green','Blue'].map((c,i)=>`<label for="rgb-${i}">${t(c)} · GPIO ${25+i}</label><input id="rgb-${i}" data-rgb="${i}" type="range" min="0" max="255" value="${mx.rgb[i]}" class="rgb-range rgb-${i}"><div class="range-readout"><span id="rgb-num-${i}">${mx.rgb[i]}</span><span>0–255</span></div>`).join('')}${!free&&!done?`<button class="primary" id="rgb-check">${t('Check →')}</button>`:''}<div class="lab-state" id="rgb-state" role="status">${free?'':mx.msg}</div></div></div></div>`;}
function mixerPage(){const done=mx.round>=RGB_TARGETS.length;return `<section class="exercise"><div class="workbench-top"><div class="eyebrow">${t('EXPERIMENT')} / ${labNo()}</div><span class="model-tag">${t('RGB MODEL · COMMON CATHODE')}</span></div>${mixerPanel(false)}<div class="feedback ${done?'good':''}" id="lab-feedback" role="status">${done?t('All three colors mixed.'):''}</div><div class="exercise-bottom"><small>${t('Mix three target colors.')}</small><button class="primary" id="finish-lab" ${done?'':'disabled'}>${t('Complete task ↗')}</button></div></section>`;}
function setRgb(i,v){mx.rgb[i]=v;paintLed('rl',rgbCss(mx.rgb),Math.max(...mx.rgb)/255);const n=$('#rgb-num-'+i);if(n)n.textContent=v;const c=$('#rgb-sketch');if(c)c.textContent=sk(makeRgbSketch(mx.rgb));}
function knobSvg(){return `<svg class="knob" viewBox="0 0 120 124" aria-hidden="true"><path d="M23 97a52 52 0 1 1 74 0" fill="none" stroke="#c9cfbf" stroke-width="2" stroke-dasharray="2 4"/><circle cx="60" cy="60" r="42" fill="#2f3d38" stroke="#1d2925" stroke-width="2"/><g id="kb-pointer" transform="rotate(${(-135+270*kb.raw/4095).toFixed(1)} 60 60)"><path d="M60 60V24" stroke="#e5f292" stroke-width="5" stroke-linecap="round"/></g><text x="14" y="118" class="knob-label">0</text><text x="82" y="118" class="knob-label">4095</text></svg>`;}
function knobState(free){const filled=free||(String(kb.inHi).trim()!==''&&String(kb.outHi).trim()!=='');const inHi=free?4095:Number(kb.inHi),outHi=free?255:Number(kb.outHi);const ok=free||(inHi===4095&&outHi===255);const level=filled&&inHi>0&&Number.isFinite(outHi)?mapRange(kb.raw,0,inHi,0,outHi):0;return {filled,ok,level,shown:Math.max(0,Math.min(255,level))};}
const kbPassed=()=>knobState(false).ok&&kb.sawMin&&kb.sawMax;
function knobMessage(free){const s=knobState(free);if(free)return '';if(!s.filled)return t('Fill in both numbers in map().');if(s.level>255)return t('level goes above 255. analogWrite() only takes 0–255 at 8 bits, so part of the turn does nothing. Check fromHigh.');if(!s.ok)return t('The numbers don’t match the ranges yet: the ADC reads 0–4095 and analogWrite() takes 0–255.');if(!kb.sawMin||!kb.sawMax)return t('Correct ranges. Now turn the knob all the way to both ends.');return t('Full range: dark at one end, full brightness at the other.');}
function knobPanel(free){const s=knobState(free);return `<div class="knob-stage"><div>${knobSvg()}</div><div>${glowLed('kl','#ff7a3d',s.shown/255)}</div><div class="knob-serial"><div class="code-label">SERIAL MONITOR · 115200</div><pre class="serial-line" id="kb-serial">raw ${kb.raw} → level ${s.filled?s.level:'?'}</pre></div></div><label class="knob-range"><span>${t('Turn the knob (analogRead on GPIO 34)')}</span><input id="kb-raw" type="range" min="0" max="4095" step="1" value="${kb.raw}"></label><div class="lab-lower"><div><div class="code-label">SKETCH.INO · MAP()</div>${free?`<pre><code>${esc(sk(makeKnobSketch(4095,255)))}</code></pre>`:`<pre class="code-fill"><code>int level = map(raw, 0, </code><input id="kb-in" inputmode="numeric" value="${esc(kb.inHi)}" aria-label="fromHigh" placeholder="?"><code>, 0, </code><input id="kb-out" inputmode="numeric" value="${esc(kb.outHi)}" aria-label="toHigh" placeholder="?"><code>);</code></pre><pre><code id="kb-sketch">${esc(sk(makeKnobSketch(kb.inHi||'?',kb.outHi||'?')))}</code></pre>`}</div><div>${free?'':`<div class="lab-control"><div class="lab-state" id="kb-state" role="status">${knobMessage(false)}</div></div>`}</div></div>`;}
function knobUpdate(free){const s=knobState(free);if(s.ok&&s.filled){if(kb.raw<=60)kb.sawMin=true;if(kb.raw>=4035)kb.sawMax=true;}$('#kb-pointer')?.setAttribute('transform',`rotate(${(-135+270*kb.raw/4095).toFixed(1)} 60 60)`);paintLed('kl','#ff7a3d',s.shown/255);const se=$('#kb-serial');if(se)se.textContent=`raw ${kb.raw} → level ${s.filled?s.level:'?'}`;if(free)return;const sk2=$('#kb-sketch');if(sk2)sk2.textContent=sk(makeKnobSketch(kb.inHi||'?',kb.outHi||'?'));const st=$('#kb-state');const m=knobMessage(false);if(st&&st.textContent!==m)st.textContent=m;const done=kbPassed();const b=$('#finish-lab');if(b)b.disabled=!done;const f=$('#lab-feedback');if(f){f.className='feedback '+(done?'good':'');f.textContent=done?t('Your dimmer works over the whole turn.'):'';}}
function knobPage(){const done=kbPassed();return `<section class="exercise"><div class="workbench-top"><div class="eyebrow">${t('EXPERIMENT')} / ${labNo()}</div><span class="model-tag">${t('ADC MODEL · 12 BIT')}</span></div>${knobPanel(false)}<div class="feedback ${done?'good':''}" id="lab-feedback" role="status">${done?t('Your dimmer works over the whole turn.'):''}</div><div class="exercise-bottom"><small>${t('Fill in map() and turn the knob to both ends.')}</small><button class="primary" id="finish-lab" ${done?'':'disabled'}>${t('Complete task ↗')}</button></div></section>`;}
function colorLab(){return `<section class="exercise"><div class="workbench-top"><div class="eyebrow">${t('FREE PLAY')}</div><span class="model-tag">PWM · RGB · ADC</span></div><h3 class="ws-h">${t('RGB LED')}</h3>${mixerPanel(true)}<h3 class="ws-h">${t('Dimmer knob')}</h3>${knobPanel(true)}</section>`;}
function bindUnit5(){
 document.querySelectorAll('[data-cp-choice]').forEach(b=>b.onclick=()=>{const [i,n]=b.dataset.cpChoice.split('-').map(Number);cps.answers[i]=n;render();});
 document.querySelectorAll('[data-cp-input]').forEach(el=>el.addEventListener('input',()=>{cps.answers[Number(el.dataset.cpInput)]=el.value;cpReady();}));cpReady();
 $('#cp-submit')?.addEventListener('click',()=>{if(!cps.graded){cps.graded=true;render();$('#feedback')?.scrollIntoView({block:'center'});announce($('#feedback').textContent);return;}const res=grade(lesson.questions,cps.answers);if(res.filter(Boolean).length>=lesson.pass){finish();return;}res.forEach((ok,i)=>{if(!ok)delete cps.answers[i];});cps.graded=false;render();window.scrollTo(0,0);});
 $('#pwm-value')?.addEventListener('input',e=>{dm.fading=false;setDim(Number(e.target.value));});
 $('#pwm-minus')?.addEventListener('click',()=>{dm.fading=false;setDim(dm.v-1);});$('#pwm-plus')?.addEventListener('click',()=>{dm.fading=false;setDim(dm.v+1);});
 $('#pwm-fade')?.addEventListener('click',()=>{dm.fading=true;dm.fadeStart=performance.now();});
 $('#pwm-check')?.addEventListener('click',()=>{const pct=PWM_TARGETS[dm.round],d=Math.round(dm.v/255*100);if(Math.abs(dm.v-pwmValue(pct))<=3){dm.round++;dm.msg=t('Yes: {v} is about {pct}%.',{v:dm.v,pct});render();}else{dm.msg=t('Not yet: {v} is {d}%. Target: {pct}%.',{v:dm.v,d,pct});$('#pwm-state').textContent=dm.msg;}announce(dm.msg);});
 document.querySelectorAll('[data-rgb]').forEach(el=>el.addEventListener('input',()=>setRgb(Number(el.dataset.rgb),Number(el.value))));
 $('#rgb-check')?.addEventListener('click',()=>{const tg=RGB_TARGETS[mx.round];if(colorClose(mx.rgb,tg.rgb)){mx.round++;mx.msg=t('{name} matched.',{name:t(tg.name)});render();}else{const names=['red','green','blue'];mx.msg=t('Not quite: {list}.',{list:mx.rgb.map((v,i)=>Math.abs(v-tg.rgb[i])>40?t(v>tg.rgb[i]?'less {c}':'more {c}',{c:t(names[i])}):null).filter(Boolean).join(', ')});$('#rgb-state').textContent=mx.msg;}announce(mx.msg);});
 const free=view==='workshop';
 $('#kb-raw')?.addEventListener('input',e=>{kb.raw=Number(e.target.value);knobUpdate(free);});
 $('#kb-in')?.addEventListener('input',e=>{kb.inHi=e.target.value.trim();kb.sawMin=kb.sawMax=false;knobUpdate(false);});
 $('#kb-out')?.addEventListener('input',e=>{kb.outHi=e.target.value.trim();kb.sawMin=kb.sawMax=false;knobUpdate(false);});
 $('#ws-program')?.addEventListener('change',e=>{lesson={mode:e.target.value};invalidate();pressed=false;render();});
 document.querySelectorAll('[data-ws]').forEach(b=>b.onclick=()=>{ws.tab=b.dataset.ws;invalidate();render();});
}
